protocol OrderRepository { func overdue(on: Date) throws -> [Order]; func add(_ order: Order) throws }

struct SwiftDataOrderRepository: OrderRepository {
    let context: ModelContext                       // actor-isolated, not shared

    func overdue(on date: Date) throws -> [Order] {
        let descriptor = FetchDescriptor<Order>(predicate: #Predicate { $0.due < date })
        return try context.fetch(descriptor)        // the framework does the mapping
    }
    func add(_ order: Order) throws { context.insert(order) }   // save at the unit-of-work edge
}

